<style>
.unifco-language-switcher{display:inline-flex;align-items:center;gap:3px;padding:3px;background:#eef3f8;border:1px solid #dbe3ec;border-radius:9px}.unifco-language-switcher button{border:0;background:transparent;color:#1e315b;padding:6px 9px;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer}.unifco-language-switcher button.active{background:#1e315b;color:#fff}html[dir="rtl"] body{direction:rtl}html[dir="rtl"] .main{text-align:right}html[dir="rtl"] table th,html[dir="rtl"] table td{text-align:right}
</style>
<script>
(function(){const D={'Operations Command Center':'مركز العمليات التشغيلية','Dashboard':'لوحة التحكم','Business':'الأعمال','Finance':'المالية','Human Resources':'الموارد البشرية','Procurement':'المشتريات','Inventory':'المخزون','Warehouse & Field Inventory':'مخزون المستودعات والمواقع','CRM':'إدارة علاقات العملاء','Customer Management':'إدارة العملاء','Customers':'العملاء','New Customer':'عميل جديد','Customer Onboarding':'تسجيل العميل','Customer Contracts':'عقود العملاء','Service Requests':'طلبات الخدمة','Work Orders':'أوامر العمل','Projects':'المشاريع','Manufacturing':'التصنيع','Maintenance':'الصيانة','Enterprise Assets':'إدارة الأصول','Finance Core':'النظام المالي','Manufacturing Operations':'عمليات التصنيع','Maintenance & EAM Operations':'عمليات الصيانة وإدارة الأصول','Scheduling & Dispatch':'الجدولة والتوجيه','Technician Mobile':'تطبيق الفني','Platform':'المنصة','AI Assistant':'المساعد الذكي','Executive Reporting':'التقارير التنفيذية','Documents':'المستندات','Notifications':'الإشعارات','Approvals':'الموافقات','Audit Trail':'سجل التدقيق','Permissions':'الصلاحيات','API Tokens':'رموز API','Logout':'تسجيل الخروج','UNIFCO Operations Command Center':'مركز عمليات يونيفكو','Asset Health':'صحة الأصول','Attention':'يحتاج انتباه','Operational Health Score':'مؤشر صحة العمليات','Global Scope Filters':'فلاتر النطاق','Customer':'العميل','Site':'الموقع','Contract':'العقد','Activity Window':'الفترة الزمنية','All Customers':'كل العملاء','All Sites':'كل المواقع','All Contracts':'كل العقود','Apply':'تطبيق','Reset':'إعادة ضبط','Month-over-Month':'مقارنة شهرية','Revenue':'الإيرادات','Work Orders Opened':'أوامر العمل المفتوحة','Work Orders Completed':'أوامر العمل المكتملة','Decision KPIs':'مؤشرات القرار','OPEN WORK ORDERS':'أوامر العمل المفتوحة','OVERDUE PM':'صيانة وقائية متأخرة','CRITICAL ASSETS':'أصول حرجة','SERVICE REQUESTS':'طلبات الخدمة','PM COMPLIANCE':'الالتزام بالصيانة','SLA PERFORMANCE':'أداء اتفاقية مستوى الخدمة','SPARE PART ALERTS':'تنبيهات قطع الغيار','OUTSTANDING AR':'الذمم المدينة','Maintenance Operations':'عمليات الصيانة','Action Required':'يحتاج إجراء','Open':'مفتوح','In Progress':'قيد التنفيذ','Waiting Parts':'بانتظار القطع','Overdue':'متأخر'};const R=Object.fromEntries(Object.entries(D).map(([a,b])=>[b,a]));function t(m){const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT),n=[];while(w.nextNode())n.push(w.currentNode);n.forEach(x=>{const s=x.nodeValue.trim();if(s&&m[s])x.nodeValue=x.nodeValue.replace(s,m[s])});document.querySelectorAll('option').forEach(o=>{const s=o.textContent.trim();if(m[s])o.textContent=m[s]})}function set(l){const c=document.documentElement.dataset.unifcoLang||'en';if(c!==l)t(l==='ar'?D:R);document.documentElement.lang=l;document.documentElement.dir=l==='ar'?'rtl':'ltr';document.documentElement.dataset.unifcoLang=l;localStorage.setItem('unifco_language',l);document.querySelectorAll('.unifco-language-switcher button').forEach(b=>b.classList.toggle('active',b.dataset.lang===l))}function m(){const u=document.querySelector('.user-name');if(!u||document.querySelector('.unifco-language-switcher'))return;const x=document.createElement('span');x.className='unifco-language-switcher';x.innerHTML='<button type="button" data-lang="ar">العربية</button><button type="button" data-lang="en">English</button>';u.insertAdjacentElement('afterend',x);x.onclick=e=>{const b=e.target.closest('button[data-lang]');if(b)set(b.dataset.lang)};document.documentElement.dataset.unifcoLang='en';x.querySelector('[data-lang="en"]').classList.add('active');if((localStorage.getItem('unifco_language')||'en')==='ar')set('ar')}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',m):m()})();
</script>
